# app/logic/brand.R
# ---------------------------------------------------------------------------
# Embedded brand assets (base64 data URIs) so no static-file serving is
# needed. Exports the app logo URI and the ordered sponsor list. UI tags are
# assembled in app/main.R. BIA logo has had its white background flood-
# filled to transparent so it blends on the frosted sponsor plate.
# ---------------------------------------------------------------------------

#' @export
logo_uri <- "data:image/png;base64,"

#' Ordered sponsor logos: USGS, FWS, USDA FS, BIA, NPS, SERDP/ESTCP
#' @export
sponsors <- list(
  list(alt = "USGS", cls = "usgs", uri = "data:image/png;base64,"),
  list(alt = "U.S. Fish & Wildlife Service", cls = "", uri = "data:image/png;base64,"),
  list(alt = "USDA Forest Service", cls = "", uri = "data:image/png;base64,"),
  list(alt = "Bureau of Indian Affairs", cls = "bia", uri = "data:image/png;base64,"),
  list(alt = "National Park Service", cls = "", uri = "data:image/png;base64,"),
  list(alt = "SERDP / ESTCP", cls = "serdp", uri = "data:image/png;base64,")
)
